/* Shared compact training editor and responsive application layout. */
function compactSetLabel(rows,i){let s=rows[i],kind=s.type||'normal';return kind==='warmup'?'W':kind==='failure'?'F':kind==='dropset'?'D':rows.slice(0,i+1).filter(x=>(x.type||'normal')==='normal').length}
function compactPrevious(s,index){let a=state.active,key=exerciseKey(s),past=state.sessions.filter(x=>sessionTime(x)<a.started&&x.sets.some(y=>exerciseKey(y)===key)).sort((x,y)=>sessionTime(y)-sessionTime(x))[0];if(!past)return '—';let type=s.type||'normal',ordinal=a.sets.slice(0,index+1).filter(x=>x.group===s.group&&(x.type||'normal')===type).length-1,p=past.sets.filter(x=>exerciseKey(x.exercise)===key&&(x.type||'normal')===type)[ordinal];return p?setPerformance(p):'—'}
function compactFields(s){let t=setTracking(s);return [['weight_reps','weight_duration','weight_distance'].includes(t)?['kg','kg',0,2000,.5]:null,['weight_reps','reps'].includes(t)?['reps','Reps',1,1000,1]:null,['duration','weight_duration','distance_duration'].includes(t)?['duration_seconds','Time',0,59999,1]:null,['weight_distance','distance_duration'].includes(t)?['distance_meters','Metres',0,1000000,1]:null].filter(Boolean)}
function compactInput(s,i,field,routineIndex=null){let [k,label,min,max,step]=field,isTime=k==='duration_seconds',value=isTime?(s[k]!=null?formatRest(s[k]):''):s[k]??'',handler=routineIndex===null?`compactUpdateSet(${i},'${k}',this.value)`:`compactRoutineValue(${routineIndex},${i},'${k}',this.value)`;return `<input aria-label="Set ${i+1} ${label}" ${isTime?'type="text" inputmode="text" placeholder="m:ss"':'type="number" inputmode="decimal" min="'+min+'" max="'+max+'" step="'+step+'"'} value="${value}" onchange="${handler}">`}
function compactUpdateSet(i,k,v){updateRichSet(i,k,v);let button=document.querySelector('[data-complete="'+i+'"]');if(button){button.classList.remove('checked');button.setAttribute('aria-pressed','false')}}
activeWorkout=function(){let a=state.active,groups=[...new Set(a.sets.map(s=>s.group))],volume=a.sets.filter(s=>s.done).reduce((n,s)=>n+(s.kg||0)*(s.reps||0),0);return `<section class="card compact-workout"><div class="card-head"><div><span class="eyebrow">Workout in progress</span><h2>${esc(a.name)}</h2></div><button class="btn small" onclick="finishWorkout()">Finish</button></div><div class="compact-summary"><span>Duration<strong>${Math.floor((Date.now()-a.started)/60000)} min</strong></span><span>Volume<strong>${round(volume)} kg</strong></span><span>Sets<strong>${a.sets.filter(s=>s.done).length}</strong></span></div><details class="compact-details"><summary>Workout details</summary><label for="session-name">Name</label><input id="session-name" maxlength="120" value="${esc(a.name)}" onchange="state.active.name=this.value.trim()||'Workout';save()"><label for="session-note">Notes</label><textarea id="session-note" maxlength="3000" onchange="state.active.notes=this.value;save()">${esc(a.notes||'')}</textarea></details>${groups.map(group=>{let rows=a.sets.filter(s=>s.group===group),first=rows[0],fields=compactFields(first),r=restState(group);return `<section class="compact-exercise"><div class="compact-exercise-head"><h3>${esc(first.exercise)}</h3><button class="icon-btn" aria-label="Exercise options" onclick="compactExerciseOptions(${group})">⋯</button></div><div class="compact-tools"><details class="compact-rest"><summary>◷ Rest <span id="compact-rest-${group}">${formatRest(restRemaining(r))}</span></summary>${exerciseRestUI(group)}</details><button class="btn secondary small" onclick="compactExerciseNote(${group})">${first.notes?'●':'＋'} Note</button>${first.superset_id?`<span class="tag">Superset ${esc(first.superset_id)}</span>`:''}</div><div class="compact-set-head" style="--metric-count:${fields.length}"><span>Set</span><span>Previous</span>${fields.map(f=>'<span>'+f[1]+'</span>').join('')}<span>✓</span></div>${rows.map((s,j)=>{let i=a.sets.indexOf(s);return `<div style="--metric-count:${fields.length}" class="compact-set-row ${s.done?'completed':''}"><button class="set-kind ${s.type==='warmup'?'warmup':''}" aria-label="Set ${j+1} type: ${esc(s.type||'normal')}" onclick="compactSetMenu(${i})">${compactSetLabel(rows,j)}</button><button class="compact-previous" aria-label="Copy previous set values" onclick="copyPreviousSet(${i})">${esc(compactPrevious(s,i))}</button>${fields.map(f=>compactInput(s,i,f)).join('')}<button data-complete="${i}" class="check-set ${s.done?'checked':''}" aria-label="Complete set ${j+1}" aria-pressed="${!!s.done}" onclick="toggleRichSet(${i})">✓</button></div>`}).join('')}<button class="btn secondary full compact-add-set" onclick="addWorkoutSet(${group})">＋ Add Set</button></section>`}).join('')||'<div class="empty">Add your first exercise to get started.</div>'}<button class="btn full" onclick="addExerciseModal()">＋ Add Exercise</button><button class="text-btn full compact-discard" onclick="cancelWorkout()">Discard workout</button></section>`};
function compactSetMenu(index,exIndex=null){let s=exIndex===null?state.active.sets[index]:compactRoutineRows(exIndex)[index];modal(modalHead('Set type')+`<div class="set-type-options">${setKinds.map(([k,t])=>`<button class="btn ${k===(s.type||'normal')?'':'secondary'}" onclick="compactChooseType(${index},'${k}',${exIndex})"><strong>${k==='warmup'?'W':k==='normal'?'1':k==='failure'?'F':'D'}</strong>${t}</button>`).join('')}</div>${exIndex===null?`<label for="compact-rpe">RPE (optional)</label><input id="compact-rpe" type="number" min="1" max="10" step=".5" value="${s.rpe??''}" onchange="updateRichSet(${index},'rpe',this.value)"><button class="text-btn full" onclick="removeWorkoutSet(${index});closeModal()">Remove set</button>`:`<button class="text-btn full" onclick="compactRemoveRoutineSet(${exIndex},${index})">Remove set</button>`}`)}
function compactChooseType(i,type,exIndex){if(!canUseForma())return;if(exIndex===null){updateRichSet(i,'type',type);closeModal();render()}else{compactRoutineRows(exIndex)[i].type=type;renderRoutineBuilder()}}
function compactExerciseNote(group){let first=state.active.sets.find(s=>s.group===group);modal(modalHead('Exercise note')+`<form onsubmit="event.preventDefault();setExerciseMetadata(${group},'notes',document.getElementById('compact-note').value);closeModal();render()"><textarea id="compact-note" maxlength="1000" placeholder="Setup or cues…">${esc(first.notes||'')}</textarea><button class="btn full">Save note</button></form>`)}
function compactExerciseOptions(group){let first=state.active.sets.find(s=>s.group===group);modal(modalHead(esc(first.exercise))+`<label for="compact-tracking">Track as</label><select id="compact-tracking" onchange="setExerciseTracking(${group},this.value);closeModal()">${[['weight_reps','Weight & reps'],['reps','Reps only'],['duration','Time'],['weight_duration','Weight & time'],['distance_duration','Distance & time'],['weight_distance','Weight & distance']].map(([k,t])=>`<option value="${k}" ${setTracking(first)===k?'selected':''}>${t}</option>`).join('')}</select><label for="compact-superset">Superset group</label><input id="compact-superset" maxlength="30" value="${esc(first.superset_id||'')}" onchange="setExerciseMetadata(${group},'superset_id',this.value||null)"><button class="btn full" onclick="closeModal();render()">Done</button>`)}
function compactRoutineRows(i){let e=routineDraft.exercises[i];if(!e.setDetails)e.setDetails=Array.from({length:e.sets},()=>({kg:e.kg??0,reps:e.reps??10,type:'normal'}));return e.setDetails}
renderRoutineBuilder=function(){if(!routineDraft)return;let d=routineDraft;modal(modalHead(d.id?'Edit routine':'Create routine')+`<form onsubmit="saveBuiltRoutine(event)"><div class="form-grid"><div><label for="builder-name">Name</label><input id="builder-name" required maxlength="100" placeholder="Routine name" value="${esc(d.name)}" oninput="routineDraft.name=this.value"></div><div><label for="builder-folder">Folder</label><select id="builder-folder" onchange="routineDraft.folderId=this.value"><option value="">No folder</option>${state.folders.map(f=>`<option value="${f.id}" ${d.folderId===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div></div>${d.exercises.map((e,i)=>{let rows=compactRoutineRows(i),fields=compactFields(rows[0]);return `<section class="compact-exercise"><div class="compact-exercise-head"><h3>${esc(e.name)}</h3><details class="compact-order"><summary aria-label="Exercise options">⋯</summary><button type="button" class="text-btn" ${i===0?'disabled':''} onclick="moveRoutineExercise(${i},-1)">Move up</button><button type="button" class="text-btn" ${i===d.exercises.length-1?'disabled':''} onclick="moveRoutineExercise(${i},1)">Move down</button><button type="button" class="text-btn" onclick="removeRoutineExercise(${i})">Remove</button></details></div><details class="compact-details"><summary>◷ Rest ${formatRest(e.rest??90)}${e.notes?' · Note':''}</summary><label>Rest · m:ss</label><input aria-label="Rest time" pattern="[0-9]{1,2}:[0-5][0-9]" value="${formatRest(e.rest??90)}" onchange="editRoutineExercise(${i},'rest',this)"><div class="rest-controls">${[["−15s",-15],["60s",60],["90s",90],["+15s",15]].map(([label,value])=>`<button type="button" class="btn secondary small" onclick="compactRoutineRest(${i},${value},${Math.abs(value)===15})">${label}</button>`).join('')}</div><label>Note</label><input aria-label="Exercise note" maxlength="1000" value="${esc(e.notes||'')}" onchange="routineDraft.exercises[${i}].notes=this.value"></details><div class="compact-routine-head" style="--metric-count:${fields.length}"><span>Set</span>${fields.map(f=>'<span>'+f[1]+'</span>').join('')}<span></span></div>${rows.map((s,j)=>`<div class="compact-routine-row" style="--metric-count:${fields.length}"><button type="button" class="set-kind ${s.type==='warmup'?'warmup':''}" aria-label="Set ${j+1} type" onclick="compactSetMenu(${j},${i})">${compactSetLabel(rows,j)}</button>${fields.map(f=>compactInput(s,j,f,i)).join('')}<button type="button" class="text-btn" aria-label="Remove set ${j+1}" onclick="compactRemoveRoutineSet(${i},${j})">×</button></div>`).join('')}<button type="button" class="btn secondary full compact-add-set" onclick="compactAddRoutineSet(${i})">＋ Add Set</button></section>`}).join('')||'<div class="empty">Add exercises to build your routine.</div>'}<button type="button" class="btn secondary full" onclick="exercisePickerTarget='routine';openExercisePicker()">＋ Add Exercise</button><div class="actions"><button type="button" class="btn secondary" onclick="cancelRoutineBuilder()">Cancel</button><button class="btn">Save routine</button></div></form>`);$('#modal').classList.add('catalog-modal','compact-builder');$('#modal-content').querySelectorAll('.set-kind').forEach(x=>x.type='button')};
function compactRoutineValue(ex,i,k,v){if(!canUseForma())return;let s=compactRoutineRows(ex)[i],n;if(k==='duration_seconds'){let m=/^(\d{1,4}):([0-5]\d)$/.exec(v);if(!m){toast('Use m:ss');return}n=+m[1]*60 + +m[2]}else n=nullableNumber(v);if(n!==null&&(!Number.isFinite(n)||n<0||(k==='reps'&&(!Number.isInteger(n)||n<1)))){toast('Check set value');return}s[k]=n;let e=routineDraft.exercises[ex];e.reps=e.setDetails[0].reps??0;e.kg=e.setDetails[0].kg??0}
function compactAddRoutineSet(ex){let rows=compactRoutineRows(ex);if(rows.length>=20){toast('Maximum 20 sets per exercise');return}rows.push({...structuredClone(rows.at(-1)),type:'normal',done:false});routineDraft.exercises[ex].sets=rows.length;renderRoutineBuilder()}
function compactRemoveRoutineSet(ex,i){let rows=compactRoutineRows(ex);if(rows.length<=1){toast('Keep at least one set');return}rows.splice(i,1);routineDraft.exercises[ex].sets=rows.length;renderRoutineBuilder()}
const compactRefreshRest=refreshRest;refreshRest=function(group,force=false){compactRefreshRest(group,force);let label=$('#compact-rest-'+group);if(label)label.textContent=formatRest(restRemaining(restState(group)))};
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('compact-builder'));
const compactCompleteSet=toggleRichSet;toggleRichSet=function(i){if(!canUseForma())return;let s=state.active?.sets[i],wasDone=s?.done,group=s?.group;compactCompleteSet(i);if(!wasDone&&state.active?.sets[i]?.done)runRest(group)};
for(const name of ['compactUpdateSet','compactChooseType','compactRoutineValue','compactAddRoutineSet','compactRemoveRoutineSet']){let operation=window[name];window[name]=function(...args){if(!canUseForma())return;return operation.apply(this,args)}}

function compactRoutineRest(i,value,adjust){if(!canUseForma())return;let e=routineDraft.exercises[i];e.rest=Math.max(0,Math.min(5999,adjust?(e.rest??90)+value:value));renderRoutineBuilder()}
